function validate([n, nums, maxDiff, queries]) {
  if (n < 1 || n > 100000) return 'n is between 1 and 10^5.';
  if (nums.length !== n) return 'nums must hold exactly n values.';
  if (nums.some(v => v < 0 || v > 100000)) return 'Each value in nums is between 0 and 10^5.';
  if (maxDiff < 0 || maxDiff > 100000) return 'maxDiff is between 0 and 10^5.';
  if (queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 pairs.';
  if (queries.some(q => q.length !== 2 || q.some(node => node < 0 || node >= n))) return 'Each query is a pair [u, v] of nodes between 0 and n - 1.';
  return null;
}

