function pathExistenceQueries(n, nums, maxDiff, queries) {
  // Sorting by value lines the nodes up on the number line.
  const order = Array.from({ length: n }, (_, i) => i).sort((a, b) => nums[a] - nums[b]);
  const values = order.map(i => nums[i]);
  const position = new Array(n);
  for (let p = 0; p < n; p++) {
    position[order[p]] = p;
  }
  // jump[0][p]: the farthest sorted position one edge away from position p.
  const jump = [new Array(n)];
  let reach = 0;
  for (let p = 0; p < n; p++) {
    while (reach + 1 < n && values[reach + 1] - values[p] <= maxDiff) {
      reach++;
    }
    jump[0][p] = reach;
  }
  // jump[k][p]: where 2^k farthest jumps from position p end.
  let levels = 1;
  while ((1 << levels) < n) {
    levels++;
  }
  for (let k = 1; k < levels; k++) {
    jump.push(jump[k - 1].map(halfway => jump[k - 1][halfway]));
  }
  const answer = [];
  for (const [u, v] of queries) {
    if (u === v) {
      answer.push(0);
      continue;
    }
    let from = Math.min(position[u], position[v]);
    const to = Math.max(position[u], position[v]);
    let steps = 0;
    for (let k = levels - 1; k >= 0; k--) {
      if (jump[k][from] < to) {
        from = jump[k][from];
        steps += 1 << k;
      }
    }
    answer.push(jump[0][from] >= to ? steps + 1 : -1);
  }
  return answer;
}

