function pathExistenceQueries(n, nums, maxDiff, queries) {
  // Breadth-first search from u over the explicit graph, once per query.
  return queries.map(([u, v]) => {
    const dist = new Array(n).fill(-1);
    dist[u] = 0;
    const queue = [u];
    for (let head = 0; head < queue.length; head++) {
      const x = queue[head];
      for (let y = 0; y < n; y++) {
        if (dist[y] === -1 && Math.abs(nums[x] - nums[y]) <= maxDiff) {
          dist[y] = dist[x] + 1;
          queue.push(y);
        }
      }
    }
    return dist[v];
  });
}

