function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 9);
  const shuffle = list => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  let nums, maxDiff;
  const style = Math.floor(rand() * 3);
  if (style === 0) {
    // Evenly spaced values: a long chain where every jump is exactly one step.
    const step = large ? 50 : 1 + Math.floor(rand() * 5);
    nums = shuffle(Array.from({ length: n }, (_, i) => i * step));
    maxDiff = step * (1 + Math.floor(rand() * 2)) - (rand() < 0.3 ? 1 : 0);
  } else if (style === 1 || large) {
    // Random values with a moderate maxDiff: gaps split the graph into a few long components.
    const span = large ? 100000 : 30;
    nums = Array.from({ length: n }, () => Math.floor(rand() * (span + 1)));
    maxDiff = large ? 150 + Math.floor(rand() * 450) : Math.floor(rand() * 8);
  } else {
    nums = Array.from({ length: n }, () => Math.floor(rand() * 100001));
    maxDiff = Math.floor(rand() * 100001);
  }
  const count = large ? 2000 : 1 + Math.floor(rand() * 8);
  const queries = Array.from({ length: count }, () => {
    const u = Math.floor(rand() * n);
    return [u, rand() < (large ? 0.02 : 0.15) ? u : Math.floor(rand() * n)];
  });
  return [n, nums, maxDiff, queries];
}
